//! A WebSocket client for bidirectional JSON-RPC, for native targets and for the browser.
//!
//! [`Client`] calls methods on the server ([`Client::call`], [`Client::notify`]), receives the
//! server's notifications ([`Client::on_notification`]), answers calls the server makes to it
//! ([`Client::on_rpc_request`]) and subscribes to topic broadcasts ([`Client::subscribe`]).
//! Build one with [`ClientBuilder`]. It does not reconnect on its own; [`ReconnectConfig`] helps
//! a caller-managed retry loop with backoff.
//!
//! Code generated by `ras-jsonrpc-bidirectional-macro` wraps this client in a typed
//! `<Name>Client`, so most applications use it through that. The generated code reaches `serde`,
//! `serde_json` and `tokio` through this crate, so the API crate does not list them for the
//! client side.
//!
//! [`Client::call`] returns the raw `JsonRpcResponse`; a JSON-RPC error from the server is an
//! `Ok` response with `error` set. [`ClientError`] is `#[non_exhaustive]`.
//!
//! # Cargo features
//!
//! - `native` (default): the transport for non-`wasm32` targets, on `tokio-tungstenite`. The token
//!   is sent as `Authorization: Bearer <token>`.
//! - `wasm`: the browser transport, on the `web-sys` WebSocket. Use it with
//!   `default-features = false`. The token is offered as the `token.<jwt>` subprotocol, because a
//!   browser cannot set headers on a WebSocket.
//!
//! Tokens are never placed in the URL. See the [README] for examples.
//!
//! [README]: https://github.com/JedimEmO/rust-api-stack/blob/master/crates/rpc/bidirectional/ras-jsonrpc-bidirectional-client/README.md

use async_trait::async_trait;
use ras_jsonrpc_bidirectional_types::{BidirectionalMessage, ConnectionId};
use ras_jsonrpc_types::{JsonRpcRequest, JsonRpcResponse};
use serde_json::Value;
use std::sync::Arc;

pub mod client;
pub mod config;
pub mod error;

#[doc(hidden)]
#[path = "private.rs"]
pub mod __private;

#[cfg(not(target_arch = "wasm32"))]
pub mod native;

#[cfg(target_arch = "wasm32")]
pub mod wasm;

pub use client::{Client, ClientBuilder};
pub use config::{ClientConfig, ReconnectConfig};
pub use error::ClientError;

/// Type alias for notification handlers
pub type NotificationHandler = Arc<dyn Fn(&str, &Value) + Send + Sync>;

/// Type alias for RPC request handlers (server-to-client RPC calls)
pub type RpcRequestHandler = Arc<
    dyn Fn(
            JsonRpcRequest,
        ) -> std::pin::Pin<
            Box<dyn std::future::Future<Output = ras_jsonrpc_types::JsonRpcResponse> + Send>,
        > + Send
        + Sync,
>;

/// Type alias for connection event handlers
pub type ConnectionEventHandler = Arc<dyn Fn(ConnectionEvent) + Send + Sync>;

/// Connection lifecycle events
#[derive(Debug, Clone)]
pub enum ConnectionEvent {
    /// Emitted after the server sends a connection-established message.
    Connected { connection_id: ConnectionId },
    /// Emitted when the server closes the connection or `Client::disconnect` completes.
    Disconnected { reason: Option<String> },
    /// Reserved for caller-managed reconnect orchestration.
    ///
    /// The current client does not spawn a background reconnect loop.
    Reconnecting { attempt: u32 },
    /// Reserved for caller-managed reconnect orchestration.
    ///
    /// The current client does not spawn a background reconnect loop.
    ReconnectFailed { attempt: u32, error: String },
    /// Reserved for transports or wrappers that surface authentication failures as events.
    AuthenticationFailed { error: String },
}

/// Trait for WebSocket transport implementations
#[cfg(not(target_arch = "wasm32"))]
pub trait TransportThreadBounds: Send + Sync {}

#[cfg(not(target_arch = "wasm32"))]
impl<T: Send + Sync> TransportThreadBounds for T {}

#[cfg(target_arch = "wasm32")]
pub trait TransportThreadBounds {}

#[cfg(target_arch = "wasm32")]
impl<T> TransportThreadBounds for T {}

#[cfg_attr(target_arch = "wasm32", async_trait(?Send))]
#[cfg_attr(not(target_arch = "wasm32"), async_trait)]
pub trait WebSocketTransport: TransportThreadBounds {
    /// Connect to the WebSocket server
    async fn connect(&mut self) -> error::ClientResult<()>;

    /// Disconnect from the WebSocket server
    async fn disconnect(&mut self) -> error::ClientResult<()>;

    /// Send a message to the server
    async fn send(&mut self, message: &BidirectionalMessage) -> error::ClientResult<()>;

    /// Receive the next message from the server
    async fn receive(&mut self) -> error::ClientResult<Option<BidirectionalMessage>>;

    /// Check if the connection is currently active
    fn is_connected(&self) -> bool;

    /// Get the connection URL
    fn url(&self) -> &str;
}

/// Pending request waiting for a response
#[derive(Debug)]
pub struct PendingRequest {
    pub id: Value,
    pub sender: tokio::sync::oneshot::Sender<JsonRpcResponse>,
    pub created_at: std::time::Instant,
}

/// Request timeout configuration
#[derive(Debug, Clone)]
pub struct RequestTimeout {
    pub duration: std::time::Duration,
}

impl Default for RequestTimeout {
    fn default() -> Self {
        Self {
            duration: std::time::Duration::from_secs(30),
        }
    }
}

/// Client state tracking
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum ClientState {
    Disconnected,
    Connecting,
    Connected,
    Reconnecting,
    Failed,
}

/// Subscription tracking
#[derive(Clone)]
pub struct Subscription {
    pub topic: String,
    pub handler: NotificationHandler,
    pub created_at: std::time::Instant,
}

impl std::fmt::Debug for Subscription {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Subscription")
            .field("topic", &self.topic)
            .field("created_at", &self.created_at)
            .finish()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_connection_event_debug() {
        let event = ConnectionEvent::Connected {
            connection_id: ConnectionId::new(),
        };
        assert!(format!("{:?}", event).contains("Connected"));
    }

    #[test]
    fn test_client_state() {
        assert_eq!(ClientState::Disconnected, ClientState::Disconnected);
        assert_ne!(ClientState::Connected, ClientState::Disconnected);
    }

    #[test]
    fn test_request_timeout_default() {
        let timeout = RequestTimeout::default();
        assert_eq!(timeout.duration.as_secs(), 30);
    }
}
